    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Convert to dict to easier take config elements
        configuration = {item["name"]: item["value"] for item in self.configuration}
        self.config = OpenIDConnectConfig(
            client_id=configuration["client_id"],
            client_secret=configuration["client_secret"],
            enable_refresh_token=configuration["enable_refresh_token"],
            json_web_key_set_url=configuration["json_web_key_set_url"],
            authorization_url=configuration["oauth_authorization_url"],
            token_url=configuration["oauth_token_url"],
            logout_url=configuration["oauth_logout_url"],
            audience=configuration["audience"],
            use_scope_permissions=configuration["use_oauth_scope_permissions"],
            user_info_url=configuration["user_info_url"],
            staff_user_domains=configuration["staff_user_domains"],
            default_group_name=configuration["default_group_name_for_new_staff_users"],
        )

        # Determine, if we have defined all fields required to use OAuth access token
        # as Saleor's authorization token.
        self.use_oauth_access_token = bool(
            self.config.user_info_url and self.config.json_web_key_set_url
        )

        # Determine, if we have defined all fields required to process the
        # authorization flow.
        self.use_authorization_flow = bool(
            self.config.json_web_key_set_url
            and self.config.authorization_url
            and self.config.token_url
        )
        self.oauth = self._get_oauth_session()

    @classmethod
    def validate_plugin_configuration(
        cls, plugin_configuration: "PluginConfiguration", **kwargs
    ):
        """Validate if provided configuration is correct."""
        incorrect_fields = get_incorrect_fields(plugin_configuration)
        if incorrect_fields:
            error_msg = "To enable a plugin, you need to provide values for this field."
            raise ValidationError(
                {
                    field: ValidationError(
                        error_msg, code=PluginErrorCode.PLUGIN_MISCONFIGURED.value
                    )
                    for field in incorrect_fields
                }
            )

    def _get_oauth_session(self):
        scope = "openid profile email"
        if self.config.use_scope_permissions:
            permissions = [f"saleor:{perm}" for perm in get_permissions_codename()]
            permissions.append(SALEOR_STAFF_PERMISSION)
            scope_permissions = " ".join(permissions)
            scope += f" {scope_permissions}"
        if self.config.enable_refresh_token:
            scope += " offline_access"
        return OAuth2Client(
            client_id=self.config.client_id,
            client_secret=self.config.client_secret,
            scope=scope,
        )

    def _use_scope_permissions(self, user, scope):
        user_permissions = []
        if scope:
            permissions = get_saleor_permissions_qs_from_scope(scope)
            user_permissions = get_saleor_permission_names(permissions)
            user.effective_permissions = permissions
        return user_permissions

    def external_obtain_access_tokens(
        self, data: dict, request: WSGIRequest, previous_value
    ) -> ExternalAccessTokens:
        if not self.active:
            return previous_value

        if not self.use_authorization_flow:
            return previous_value

        code = data.get("code")
        if not code:
            msg = "Missing required field - code"
            raise ValidationError(
                {"code": ValidationError(msg, code=PluginErrorCode.NOT_FOUND.value)}
            )

        state = data.get("state")
        if not state:
            msg = "Missing required field - state"
            raise ValidationError(
                {"state": ValidationError(msg, code=PluginErrorCode.NOT_FOUND.value)}
            )

        try:
            state_data = signing.loads(state)
        except signing.BadSignature:
            msg = "Bad signature"
            raise ValidationError(
                {"state": ValidationError(msg, code=PluginErrorCode.INVALID.value)}
            )

        redirect_uri = state_data.get("redirectUri")
        if not redirect_uri:
            msg = "The state value is incorrect"
            raise ValidationError(
                {"code": ValidationError(msg, code=PluginErrorCode.INVALID.value)}
            )

        try:
            token_data = self.oauth.fetch_token(
                self.config.token_url, code=code, redirect_uri=redirect_uri
            )
        except AuthlibBaseError as error:
            raise ValidationError(
                {
                    "code": ValidationError(
                        error.description, code=PluginErrorCode.INVALID.value
                    )
                }
            )

        try:
            parsed_id_token = get_parsed_id_token(
                token_data, self.config.json_web_key_set_url
            )
            user, user_created, user_updated = get_or_create_user_from_payload(
                parsed_id_token,
                self.config.authorization_url,
            )
        except AuthenticationError as e:
            raise ValidationError(
                {"code": ValidationError(str(e), code=PluginErrorCode.INVALID.value)}
            )

        user_permissions = []
        is_staff_user_email = self.is_staff_user_email(user)
        if self.config.use_scope_permissions or is_staff_user_email:
            scope = token_data.get("scope")
            user_permissions = self._use_scope_permissions(user, scope)

            is_staff_in_scope = SALEOR_STAFF_PERMISSION in scope
            is_staff_user = is_staff_in_scope or user_permissions or is_staff_user_email
            if is_staff_user:
                assign_staff_to_default_group_and_update_permissions(
                    user, self.config.default_group_name
                )
                if not user.is_staff:
                    user.is_staff = True
                    user_updated = True
                    user.save(update_fields=["is_staff"])
            elif user.is_staff and not is_staff_user:
                user.is_staff = False
                user_updated = True
                user.save(update_fields=["is_staff"])

        if user_created or user_updated:
            send_user_event(user, user_created, user_updated)

        tokens = create_tokens_from_oauth_payload(
            token_data, user, parsed_id_token, user_permissions, owner=self.PLUGIN_ID
        )
        return ExternalAccessTokens(user=user, **tokens)

    def is_staff_user_email(self, user: "User"):
        """Return True if the user email is from staff user domains."""
        staff_user_domains = get_staff_user_domains(self.config)
        email_domain = get_domain_from_email(user.email)
        return email_domain in staff_user_domains

    def external_authentication_url(
        self, data: dict, request: WSGIRequest, previous_value
    ) -> dict:
        if not self.active:
            return previous_value

        if not self.use_authorization_flow:
            return previous_value

        redirect_uri = data.get("redirectUri")
        if not redirect_uri:
            msg = "Missing required field - redirectUri"
            raise ValidationError(
                {
                    "redirectUri": ValidationError(
                        msg, code=PluginErrorCode.NOT_FOUND.value
                    )
                }
            )
        kwargs = {
            "redirect_uri": redirect_uri,
            "state": signing.dumps({"redirectUri": redirect_uri}),
        }
        if self.config.audience:
            kwargs["audience"] = self.config.audience
        uri, state = self.oauth.create_authorization_url(
            self.config.authorization_url, **kwargs
        )
        return {"authorizationUrl": uri}

    def external_refresh(
        self, data: dict, request: WSGIRequest, previous_value
    ) -> ExternalAccessTokens:
        if not self.active:
            return previous_value

        if not self.use_authorization_flow:
            return previous_value

        error_code = PluginErrorCode.INVALID.value
        if not self.config.enable_refresh_token:
            msg = (
                "Unable to refresh the token. Support for refreshing tokens is disabled"
            )
            raise ValidationError(
                {"refresh_token": ValidationError(msg, code=error_code)}
            )
        refresh_token = request.COOKIES.get(JWT_REFRESH_TOKEN_COOKIE_NAME, None)
        refresh_token = data.get("refreshToken") or refresh_token

        validate_refresh_token(refresh_token, data)
        saleor_refresh_token = jwt_decode(refresh_token)  # type: ignore
        token_endpoint = self.config.token_url
        try:
            token_data = self.oauth.refresh_token(
                token_endpoint,
                refresh_token=saleor_refresh_token[OAUTH_TOKEN_REFRESH_FIELD],
            )
        except (AuthlibBaseError, HTTPError):
            logger.warning("Unable to refresh the token.", exc_info=True)
            raise ValidationError(
                {
                    "refresh_token": ValidationError(
                        "Unable to refresh the token.",
                        code=error_code,
                    )
                }
            )
        try:
            parsed_id_token = get_parsed_id_token(
                token_data, self.config.json_web_key_set_url
            )
            user = get_user_from_token(parsed_id_token)

            user_permissions = self.get_and_update_user_permissions(
                user, self.config.use_scope_permissions, token_data.get("scope")
            )

            tokens = create_tokens_from_oauth_payload(
                token_data,
                user,
                parsed_id_token,
                user_permissions,
                owner=self.PLUGIN_ID,
            )
            return ExternalAccessTokens(user=user, **tokens)
        except AuthenticationError as e:
            raise ValidationError(
                {"refreshToken": ValidationError(str(e), code=error_code)}
            )

    def get_and_update_user_permissions(
        self, user: User, use_scope_permissions: bool, scope: str
    ):
        """Update user permissions based on scope and user groups' permissions."""
        permissions = get_user_groups_permissions(user)
        if use_scope_permissions and scope:
            permissions |= get_saleor_permissions_qs_from_scope(scope)
        user.effective_permissions = permissions
        user_permissions = (
            get_saleor_permission_names(permissions) if permissions else []
        )
        return user_permissions

    def external_logout(self, data: dict, request: WSGIRequest, previous_value):
        if not self.active:
            return previous_value

        if not self.use_authorization_flow:
            return previous_value

        if not self.config.logout_url:
            # Logout url doesn't exist
            return {}
        req = PreparedRequest()
        req.prepare_url(self.config.logout_url, data)

        return {"logoutUrl": req.url}

    def external_verify(
        self, data: dict, request: WSGIRequest, previous_value
    ) -> tuple[Optional[User], dict]:
        if not self.active:
            return previous_value

        if not self.use_authorization_flow:
            return previous_value

        token = data.get("token")
        if not token:
            return previous_value
        valid = is_owner_of_token_valid(token, owner=self.PLUGIN_ID)
        if not valid:
            return previous_value
        try:
            payload = jwt_decode(token)
            user = get_user_from_payload(payload)
            if not user:
                return previous_value
            user.is_staff = False
        except (ExpiredSignatureError, InvalidTokenError) as e:
            raise ValidationError({"token": e})
        permissions = payload.get(PERMISSIONS_FIELD)
        if permissions:
            user.is_staff = True
            user.effective_permissions = get_permissions_from_names(permissions)
            assign_staff_to_default_group_and_update_permissions(
                user, self.config.default_group_name
            )
        return user, payload

    def authenticate_user(self, request: WSGIRequest, previous_value) -> Optional[User]:
        if not self.active:
            return previous_value
        token = get_token_from_request(request)
        if not token:
            return previous_value
        user = previous_value
        if self.use_authorization_flow and is_owner_of_token_valid(
            token, owner=self.PLUGIN_ID
        ):
            # Check if the token is created by this plugin
            try:
                payload = jwt_decode(token)
                user = get_user_from_access_payload(payload, request)
            except (InvalidTokenError, DecodeError):
                return previous_value
            if user.is_staff:
                assign_staff_to_default_group_and_update_permissions(
                    user, self.config.default_group_name
                )
            return user

        staff_user_domains = get_staff_user_domains(self.config)

        if self.use_oauth_access_token:
            try:
                user = get_user_from_oauth_access_token(
                    token,
                    self.config.json_web_key_set_url,
                    self.config.user_info_url,
                    self.config.use_scope_permissions,
                    self.config.audience,
                    staff_user_domains,
                    self.config.default_group_name,
                )
            except AuthenticationError:
                return previous_value
        return user or previous_value

from collections.abc import Iterable
from datetime import datetime, timedelta
from typing import Any, Optional

import graphene
import jwt
from django.conf import settings

from ..account.models import User
from ..app.models import App, AppExtension
from ..permission.enums import (
    get_permission_names,
    get_permissions_from_codenames,
    get_permissions_from_names,
)
from ..permission.models import Permission
from .jwt_manager import get_jwt_manager

JWT_ACCESS_TYPE = "access"
JWT_REFRESH_TYPE = "refresh"
JWT_THIRDPARTY_ACCESS_TYPE = "thirdparty"
JWT_REFRESH_TOKEN_COOKIE_NAME = "refreshToken"

APP_KEY_FIELD = "app"
PERMISSIONS_FIELD = "permissions"
USER_PERMISSION_FIELD = "user_permissions"
JWT_SALEOR_OWNER_NAME = "saleor"
JWT_OWNER_FIELD = "owner"


def jwt_base_payload(
    exp_delta: Optional[timedelta], token_owner: str
) -> dict[str, Any]:
    utc_now = datetime.utcnow()

    payload = {
        "iat": utc_now,
        JWT_OWNER_FIELD: token_owner,
        "iss": get_jwt_manager().get_issuer(),
    }
    if exp_delta:
        payload["exp"] = utc_now + exp_delta
    return payload


def jwt_user_payload(
    user: User,
    token_type: str,
    exp_delta: Optional[timedelta],
    additional_payload: Optional[dict[str, Any]] = None,
    token_owner: str = JWT_SALEOR_OWNER_NAME,
) -> dict[str, Any]:
    payload = jwt_base_payload(exp_delta, token_owner)
    payload.update(
        {
            "token": user.jwt_token_key,
            "email": user.email,
            "type": token_type,
            "user_id": graphene.Node.to_global_id("User", user.id),
            "is_staff": user.is_staff,
        }
    )
    if additional_payload:
        payload.update(additional_payload)
    return payload


def jwt_encode(payload: dict[str, Any]) -> str:
    jwt_manager = get_jwt_manager()
    return jwt_manager.encode(payload)


def jwt_decode_with_exception_handler(
    token: str, verify_expiration=settings.JWT_EXPIRE
) -> Optional[dict[str, Any]]:
    try:
        return jwt_decode(token, verify_expiration=verify_expiration)
    except jwt.PyJWTError:
        return None


def jwt_decode(
    token: str, verify_expiration=settings.JWT_EXPIRE, verify_aud: bool = False
) -> dict[str, Any]:
    jwt_manager = get_jwt_manager()
    return jwt_manager.decode(token, verify_expiration, verify_aud=verify_aud)


def create_token(payload: dict[str, Any], exp_delta: timedelta) -> str:
    payload.update(jwt_base_payload(exp_delta, token_owner=JWT_SALEOR_OWNER_NAME))
    return jwt_encode(payload)


def create_access_token(
    user: User, additional_payload: Optional[dict[str, Any]] = None
) -> str:
    payload = jwt_user_payload(
        user, JWT_ACCESS_TYPE, settings.JWT_TTL_ACCESS, additional_payload
    )
    return jwt_encode(payload)


def create_refresh_token(
    user: User, additional_payload: Optional[dict[str, Any]] = None
) -> str:
    payload = jwt_user_payload(
        user,
        JWT_REFRESH_TYPE,
        settings.JWT_TTL_REFRESH,
        additional_payload,
    )
    return jwt_encode(payload)


def get_user_from_payload(payload: dict[str, Any], request=None) -> Optional[User]:
    # TODO: dataloader
    user = User.objects.filter(email=payload["email"], is_active=True).first()
    user_jwt_token = payload.get("token")
    if not user_jwt_token or not user:
        raise jwt.InvalidTokenError(
            "Invalid token. Create new one by using tokenCreate mutation."
        )
    if user.jwt_token_key != user_jwt_token:
        raise jwt.InvalidTokenError(
            "Invalid token. Create new one by using tokenCreate mutation."
        )
    return user


def is_saleor_token(token: str) -> bool:
    """Confirm that token was generated by Saleor not by plugin."""
    try:
        payload = jwt.decode(token, options={"verify_signature": False})
    except jwt.PyJWTError:
        return False
    owner = payload.get(JWT_OWNER_FIELD)
    if not owner or owner != JWT_SALEOR_OWNER_NAME:
        return False
    return True


def get_user_from_access_payload(payload: dict, request=None) -> Optional[User]:
    jwt_type = payload.get("type")
    if jwt_type not in [JWT_ACCESS_TYPE, JWT_THIRDPARTY_ACCESS_TYPE]:
        raise jwt.InvalidTokenError(
            "Invalid token. Create new one by using tokenCreate mutation."
        )
    permissions = payload.get(PERMISSIONS_FIELD, None)
    user = get_user_from_payload(payload, request)
    if user:
        if permissions is not None:
            token_permissions = get_permissions_from_names(permissions)
            token_codenames = [perm.codename for perm in token_permissions]
            user.effective_permissions = get_permissions_from_codenames(token_codenames)
            user.is_staff = True if user.effective_permissions else False

        if payload.get("is_staff"):
            user.is_staff = True
    return user


def _create_access_token_for_third_party_actions(
    permissions: Iterable["Permission"],
    user: "User",
    app: "App",
    extra: Optional[dict[str, Any]] = None,
    database_connection_name: str = settings.DATABASE_CONNECTION_DEFAULT_NAME,
):
    app_permission_enums = get_permission_names(permissions)

    permissions = user.effective_permissions.using(database_connection_name)
    user_permission_enums = get_permission_names(permissions)
    additional_payload = {
        APP_KEY_FIELD: graphene.Node.to_global_id("App", app.id),
        PERMISSIONS_FIELD: list(app_permission_enums & user_permission_enums),
        USER_PERMISSION_FIELD: list(user_permission_enums),
    }
    if app.audience:
        additional_payload["aud"] = app.audience
    if extra:
        additional_payload.update(extra)

    payload = jwt_user_payload(
        user,
        JWT_THIRDPARTY_ACCESS_TYPE,
        exp_delta=settings.JWT_TTL_APP_ACCESS,
        additional_payload=additional_payload,
    )
    return jwt_encode(payload)


def create_access_token_for_app(
    app: "App",
    user: "User",
    database_connection_name: str = settings.DATABASE_CONNECTION_DEFAULT_NAME,
):
    """Create access token for app.

    App can use user's JWT token to proceed given operation in Saleor.
    The token which can be used by App has additional field defining the permissions
    assigned to it. The permissions set is the intersection of user permissions and
    app permissions.
    """
    app_permissions = app.permissions.all()
    return _create_access_token_for_third_party_actions(
        permissions=app_permissions,
        user=user,
        app=app,
        database_connection_name=database_connection_name,
    )


def create_access_token_for_app_extension(
    app_extension: "AppExtension",
    permissions: Iterable["Permission"],
    user: "User",
    app: "App",
    database_connection_name: str = settings.DATABASE_CONNECTION_DEFAULT_NAME,
):
    app_extension_id = graphene.Node.to_global_id("AppExtension", app_extension.id)
    return _create_access_token_for_third_party_actions(
        permissions=permissions,
        user=user,
        app=app,
        extra={"app_extension": app_extension_id},
        database_connection_name=database_connection_name,
    )

from typing import Optional

import graphene
from django.core.exceptions import ValidationError
from django.utils import timezone

from .....account import models
from .....account.error_codes import AccountErrorCode
from .....account.utils import retrieve_user_by_email
from .....core.jwt import create_access_token, create_refresh_token
from ....core import ResolveInfo
from ....core.descriptions import ADDED_IN_38
from ....core.doc_category import DOC_CATEGORY_AUTH
from ....core.mutations import BaseMutation
from ....core.types import AccountError
from ....site.dataloaders import get_site_promise
from ...types import User
from .utils import _get_new_csrf_token


class CreateToken(BaseMutation):
    """Mutation that authenticates a user and returns token and user data."""

    class Arguments:
        email = graphene.String(required=True, description="Email of a user.")
        password = graphene.String(required=True, description="Password of a user.")
        audience = graphene.String(
            required=False,
            description=(
                "The audience that will be included to JWT tokens with "
                "prefix `custom:`." + ADDED_IN_38
            ),
        )

    class Meta:
        description = "Create JWT token."
        doc_category = DOC_CATEGORY_AUTH
        error_type_class = AccountError
        error_type_field = "account_errors"

    token = graphene.String(description="JWT token, required to authenticate.")
    refresh_token = graphene.String(
        description="JWT refresh token, required to re-generate access token."
    )
    csrf_token = graphene.String(
        description="CSRF token required to re-generate access token."
    )
    user = graphene.Field(User, description="A user instance.")

    @classmethod
    def _retrieve_user_from_credentials(cls, email, password) -> Optional[models.User]:
        user = retrieve_user_by_email(email)

        if user and user.check_password(password):
            return user
        return None

    @classmethod
    def get_user(cls, info: ResolveInfo, email, password):
        site_settings = get_site_promise(info.context).get().settings
        user = cls._retrieve_user_from_credentials(email, password)
        if not user:
            raise ValidationError(
                {
                    "email": ValidationError(
                        "Please, enter valid credentials",
                        code=AccountErrorCode.INVALID_CREDENTIALS.value,
                    )
                }
            )
        if (
            not user.is_confirmed
            and not site_settings.allow_login_without_confirmation
            and site_settings.enable_account_confirmation_by_email
        ):
            raise ValidationError(
                {
                    "email": ValidationError(
                        "Account needs to be confirmed via email.",
                        code=AccountErrorCode.ACCOUNT_NOT_CONFIRMED.value,
                    )
                }
            )

        if not user.is_active:
            raise ValidationError(
                {
                    "email": ValidationError(
                        "Account inactive.",
                        code=AccountErrorCode.INACTIVE.value,
                    )
                }
            )
        return user

    @classmethod
    def perform_mutation(  # type: ignore[override]
        cls, _root, info: ResolveInfo, /, *, audience=None, email, password
    ):
        user = cls.get_user(info, email, password)
        additional_paylod = {}

        csrf_token = _get_new_csrf_token()
        refresh_additional_payload = {
            "csrfToken": csrf_token,
        }
        if audience:
            additional_paylod["aud"] = f"custom:{audience}"
            refresh_additional_payload["aud"] = f"custom:{audience}"

        access_token = create_access_token(user, additional_payload=additional_paylod)
        refresh_token = create_refresh_token(
            user, additional_payload=refresh_additional_payload
        )
        setattr(info.context, "refresh_token", refresh_token)
        info.context.user = user
        info.context._cached_user = user
        user.last_login = timezone.now()
        user.save(update_fields=["last_login", "updated_at"])
        return cls(
            errors=[],
            user=user,
            token=access_token,
            refresh_token=refresh_token,
            csrf_token=csrf_token,
        )

from typing import Optional

import graphene
from django.core.exceptions import ValidationError
from django.utils import timezone

from .....account.error_codes import AccountErrorCode
from .....core.jwt import (
    JWT_REFRESH_TOKEN_COOKIE_NAME,
    JWT_REFRESH_TYPE,
    create_access_token,
)
from ....core import ResolveInfo
from ....core.doc_category import DOC_CATEGORY_AUTH
from ....core.mutations import BaseMutation
from ....core.types import AccountError
from ...types import User
from .utils import _does_token_match, get_payload, get_user


class RefreshToken(BaseMutation):
    """Mutation that refresh user token and returns token and user data."""

    token = graphene.String(description="JWT token, required to authenticate.")
    user = graphene.Field(User, description="A user instance.")

    class Arguments:
        refresh_token = graphene.String(required=False, description="Refresh token.")
        csrf_token = graphene.String(
            required=False,
            description=(
                "CSRF token required to refresh token. This argument is "
                "required when `refreshToken` is provided as a cookie."
            ),
        )

    class Meta:
        description = (
            "Refresh JWT token. Mutation tries to take refreshToken from the input. "
            "If it fails it will try to take `refreshToken` from the http-only cookie "
            f"`{JWT_REFRESH_TOKEN_COOKIE_NAME}`. "
            "`csrfToken` is required when `refreshToken` is provided as a cookie."
        )
        doc_category = DOC_CATEGORY_AUTH
        error_type_class = AccountError
        error_type_field = "account_errors"

    @classmethod
    def get_refresh_token_payload(cls, refresh_token):
        try:
            payload = get_payload(refresh_token)
        except ValidationError as e:
            raise ValidationError({"refreshToken": e})
        return payload

    @classmethod
    def get_refresh_token(
        cls, info: ResolveInfo, refresh_token: Optional[str] = None
    ) -> Optional[str]:
        request = info.context
        if refresh_token is None:
            refresh_token = request.COOKIES.get(JWT_REFRESH_TOKEN_COOKIE_NAME, None)
        return refresh_token

    @classmethod
    def clean_refresh_token(cls, refresh_token):
        if refresh_token is None:
            raise ValidationError(
                {
                    "refresh_token": ValidationError(
                        "Missing refreshToken",
                        code=AccountErrorCode.JWT_MISSING_TOKEN.value,
                    )
                }
            )
        payload = cls.get_refresh_token_payload(refresh_token)
        if payload["type"] != JWT_REFRESH_TYPE:
            raise ValidationError(
                {
                    "refresh_token": ValidationError(
                        "Incorrect refreshToken",
                        code=AccountErrorCode.JWT_INVALID_TOKEN.value,
                    )
                }
            )
        return payload

    @classmethod
    def clean_csrf_token(cls, csrf_token, payload):
        if not csrf_token:
            msg = "CSRF token is required when refreshToken is provided by the cookie"
            raise ValidationError(
                {
                    "csrf_token": ValidationError(
                        msg,
                        code=AccountErrorCode.REQUIRED.value,
                    )
                }
            )
        is_valid = _does_token_match(csrf_token, payload["csrfToken"])
        if not is_valid:
            raise ValidationError(
                {
                    "csrf_token": ValidationError(
                        "Invalid csrf token",
                        code=AccountErrorCode.JWT_INVALID_CSRF_TOKEN.value,
                    )
                }
            )

    @classmethod
    def get_user(cls, payload):
        try:
            user = get_user(payload)
        except ValidationError as e:
            raise ValidationError({"refresh_token": e})
        return user

    @classmethod
    def perform_mutation(
        cls, _root, info: ResolveInfo, /, *, csrf_token=None, refresh_token=None
    ):
        need_csrf = refresh_token is None
        refresh_token = cls.get_refresh_token(info, refresh_token)
        payload = cls.clean_refresh_token(refresh_token)

        # None when we got refresh_token from cookie.
        if need_csrf:
            cls.clean_csrf_token(csrf_token, payload)

        user = get_user(payload)
        additional_payload = {}
        if audience := payload.get("aud"):
            additional_payload["aud"] = audience
        token = create_access_token(user, additional_payload=additional_payload)
        if user and not user.is_anonymous:
            user.last_login = timezone.now()
            user.save(update_fields=["last_login", "updated_at"])
        return cls(errors=[], user=user, token=token)

import jwt
from django.core.exceptions import ValidationError
from django.middleware.csrf import (  # type: ignore
    _get_new_csrf_string,
    _mask_cipher_secret,
    _unmask_cipher_token,
)
from django.utils.crypto import constant_time_compare

from .....account.error_codes import AccountErrorCode
from .....core.jwt import PERMISSIONS_FIELD, get_user_from_payload, jwt_decode
from .....permission.enums import get_permissions_from_names


def get_user(payload):
    try:
        user = get_user_from_payload(payload)
    except Exception:
        user = None
    if not user:
        raise ValidationError(
            "Invalid token", code=AccountErrorCode.JWT_INVALID_TOKEN.value
        )
    permissions = payload.get(PERMISSIONS_FIELD)
    if permissions is not None:
        user.effective_permissions = get_permissions_from_names(permissions)
    return user


def get_payload(token):
    try:
        payload = jwt_decode(token)
    except jwt.ExpiredSignatureError:
        raise ValidationError(
            "Signature has expired", code=AccountErrorCode.JWT_SIGNATURE_EXPIRED.value
        )
    except jwt.DecodeError:
        raise ValidationError(
            "Error decoding signature", code=AccountErrorCode.JWT_DECODE_ERROR.value
        )
    except jwt.InvalidTokenError:
        raise ValidationError(
            "Invalid token", code=AccountErrorCode.JWT_INVALID_TOKEN.value
        )
    return payload


def _get_new_csrf_token() -> str:
    return _mask_cipher_secret(_get_new_csrf_string())


def _does_token_match(token: str, csrf_token: str) -> bool:
    return constant_time_compare(
        _unmask_cipher_token(token),
        _unmask_cipher_token(csrf_token),
    )

